import (
	"fmt"
	"strconv"
	"strings"
)

type ListNode struct {
	Val  int
	Next *ListNode
}

// readList reads a count and that many values, and links them into nodes.
func readList() *ListNode {
	var count int
	fmt.Scan(&count)
	values := make([]int, count)
	for i := range values {
		fmt.Scan(&values[i])
	}
	var head *ListNode
	for i := count - 1; i >= 0; i-- {
		head = &ListNode{Val: values[i], Next: head}
	}
	return head
}

